head.script:
// spinner 는 onfocus 이벤트를 제공하지 않으므로(가이드 이벤트: onUpButtonClick, onDownButtonClick, onviewchange, oneditkeyup, oneditenter, oneditfull)
// 공통 focus 샘플(onfocus 출력) 대신 focus() 호출 후 키보드 입력으로 발생하는 oneditkeyup 으로 포커스 이동과 커서 위치를 확인한다.
scwin.tData = {
    "description" : "[spinner > M > focus]<br/>컴포넌트로 포커스를 이동시킵니다.",
    "validation" : [
        "컴포넌트로 포커스를 이동시킵니다.",
        "컴포넌트에 입력값이 있으면 커서가 텍스트 끝에 위치합니다."
    ]
}



scwin.onpageload = async function () {
    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[절차] focus 버튼 클릭 후 다른 곳을 클릭하지 말고 키보드로 숫자 1개 입력\n[확인] oneditkeyup 이 출력되면 포커스가 이동한 것이며, newValue 에서 입력한 숫자가 기존 값 끝에 붙는지 확인\n[참고] spinner 는 onfocus 이벤트를 제공하지 않아 oneditkeyup 으로 확인"', '', 'label1');

    // 조건 설정 (initValue : 입력값 유무)
    let properties = {
        initValue: con_initValue.getValue()
    };
    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["oneditkeyup"]);

    // comp 생성 함수 호출
    await $c.gcm.createBasicSpinner(cList, eList);
};



// focus() 호출
scwin.btn_focus_onclick = function (e) {
    target1.focus();
};



// 포커스가 이동했으면 키 입력 시 발생 (validation 1, 2 판정 출력)
scwin.target1_oneditkeyup = function (info, e) {
    wf_body_bottom.getObj("scwin").setReturnValue("oneditkeyup : oldValue=" + info.oldValue + ", newValue=" + info.newValue + ", keyCode=" + info.keyCode);
};
